      background: rgba(255,255,255,0.2);
    }
    .newsletter-btn {
      background: var(--orange);
      color: var(--white);
      padding: 16px 32px;
      border-radius: 50px;
      font-weight: 700;
      font-size: 1rem;
      transition: background 0.2s, transform 0.15s;
      white-space: nowrap;
    }
    .newsletter-btn:hover {
      background: var(--orange-dark);
      transform: translateY(-1px);
    }
    .newsletter-success {
      display: none;
      color: var(--white);
      font-weight: 600;
      margin-top: 16px;
      font-size: 1rem;
      align-items: center;
      justify-content: center;
      gap: 8px;
