    // Header scroll effect
    const header = document.querySelector('.header');
    window.addEventListener('scroll', () => {
      header.classList.toggle('scrolled', window.scrollY > 10);
    }, { passive: true });

    // Mobile nav toggle
    const mobileToggle = document.getElementById('mobileToggle');
    const mainNav = document.getElementById('mainNav');
    mobileToggle.addEventListener('click', () => {
      const expanded = mainNav.classList.toggle('active');
      mobileToggle.setAttribute('aria-expanded', expanded);
    });

    // Product carousel
    const track = document.getElementById('carouselTrack');
    const prevBtn = document.getElementById('carouselPrev');
    const nextBtn = document.getElementById('carouselNext');
    const cardWidth = 284; // card width + gap

    function updateCarouselButtons() {
      prevBtn.disabled = track.scrollLeft <= 5;
      nextBtn.disabled = track.scrollLeft >= track.scrollWidth - track.clientWidth - 5;
    }

    prevBtn.addEventListener('click', () => {
      track.scrollBy({ left: -cardWidth * 2, behavior: 'smooth' });
    });
    nextBtn.addEventListener('click', () => {
      track.scrollBy({ left: cardWidth * 2, behavior: 'smooth' });
    });
    track.addEventListener('scroll', updateCarouselButtons, { passive: true });
    window.addEventListener('resize', updateCarouselButtons);
    updateCarouselButtons();

    // Store locator
    const locatorForm = document.getElementById('locatorForm');
    const storeResults = document.getElementById('storeResults');
    locatorForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const zip = document.getElementById('zipInput').value.trim();
      if (zip.length > 0) {
        storeResults.classList.add('active');
        storeResults.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }
    });

    // Newsletter
    const newsletterForm = document.getElementById('newsletterForm');
    const newsletterSuccess = document.getElementById('newsletterSuccess');
    newsletterForm.addEventListener('submit', (e) => {
      e.preventDefault();
      newsletterForm.style.display = 'none';
      newsletterSuccess.classList.add('active');
    });

    // Smooth scroll for anchor links
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
      anchor.addEventListener('click', (e) => {
        const target = document.querySelector(anchor.getAttribute('href'));
        if (target) {
          e.preventDefault();
          target.scrollIntoView({ behavior: 'smooth' });
          if (mainNav.classList.contains('active')) {
            mainNav.classList.remove('active');
            mobileToggle.setAttribute('aria-expanded', 'false');
          }
        }
      });
    });
  </script>
